using System;
using NUnit.Framework;
using Round2;
using UnityEngine;
using UnityEngine.UI;
public class HiddenRulesTests {
 [Test,Category("T1")] public void EmptyDoesNotScore(){var r=LineRules.Clear(new bool[4,4]);Assert.AreEqual(0,r.Score);Assert.AreEqual(0,r.Lines);}
 [Test,Category("T1")] public void RowClearedWithoutGravity(){var b=new bool[4,4];for(int x=0;x<4;x++)b[x,1]=true;b[0,3]=true;var r=LineRules.Clear(b);Assert.AreEqual(40,r.Score);Assert.AreEqual(1,r.Lines);Assert.IsTrue(r.Board[0,3]);Assert.IsFalse(r.Board[0,1]);}
 [Test,Category("T1")] public void CrossCountsUniqueCellsAndCombo(){var b=new bool[4,4];for(int i=0;i<4;i++){b[i,0]=true;b[0,i]=true;}var r=LineRules.Clear(b);Assert.AreEqual(120,r.Score);Assert.AreEqual(2,r.Lines);Assert.IsFalse(r.Board[0,3]);}
 [Test,Category("T1")] public void TwoRowsComboAndInputUntouched(){var b=new bool[4,4];for(int x=0;x<4;x++){b[x,1]=true;b[x,2]=true;}var r=LineRules.Clear(b);Assert.AreEqual(130,r.Score);Assert.IsTrue(b[0,1]);Assert.IsFalse(r.Board[0,1]);}
 [Test,Category("T2")] public void FixedSeedSequence(){CollectionAssert.AreEqual(new[]{0,3,2},BlockSupply.Next(1));}
 [Test,Category("T2")] public void RepeatSeedAndDifferentSeed(){CollectionAssert.AreEqual(BlockSupply.Next(9),BlockSupply.Next(9));CollectionAssert.AreNotEqual(BlockSupply.Next(1),BlockSupply.Next(2));}
 [Test,Category("T2")] public void FullBoardGameOver(){var b=new bool[4,4];for(int x=0;x<4;x++)for(int y=0;y<4;y++)b[x,y]=true;Assert.IsFalse(BlockSupply.HasMove(b,new[]{0,1,2}));}
 [Test,Category("T2")] public void OnlyPendingFitDeterminesGameOver(){var b=new bool[2,2];b[0,0]=b[1,0]=b[0,1]=true;Assert.IsFalse(BlockSupply.HasMove(b,new[]{1,2,3}));Assert.IsTrue(BlockSupply.HasMove(b,new[]{0,2,3}));}
 [Test,Category("T4")] public void RoundTripAllState(){var b=new bool[3,2];b[2,1]=true;var r=GameSave.Load(GameSave.Save(new GameState{Board=b,Score=120,Pending=new[]{5,1,0}}));Assert.AreEqual(120,r.Score);Assert.AreEqual(3,r.Board.GetLength(0));Assert.AreEqual(2,r.Board.GetLength(1));Assert.IsTrue(r.Board[2,1]);CollectionAssert.AreEqual(new[]{5,1,0},r.Pending);}
 [Test,Category("T4")] public void SnapshotIndependentOfLaterMutation(){var s=new GameState{Board=new bool[2,2],Score=8,Pending=new[]{1,2,3}};var json=GameSave.Save(s);s.Board[0,0]=true;s.Pending[0]=5;var r=GameSave.Load(json);Assert.IsFalse(r.Board[0,0]);Assert.AreEqual(1,r.Pending[0]);}
 [Test,Category("T4")] public void MalformedSaveRejected(){Assert.Throws<ArgumentException>(()=>GameSave.Load("garbage"));}
 [Test,Category("T4")] public void UnsupportedSaveVersionRejected(){Assert.Throws<ArgumentException>(()=>GameSave.Load("{\"version\":2,\"width\":1,\"height\":1,\"cells\":[false],\"score\":0,\"pending\":[0,1,2]}"));}
 [Test,Category("T5S1")] public void CatalogIdsAndTargets(){var c=Levels.Catalog();Assert.AreEqual(3,c.Length);CollectionAssert.AreEqual(new[]{1,2,3},Array.ConvertAll(c,x=>x.Id));CollectionAssert.AreEqual(new[]{100,250,500},Array.ConvertAll(c,x=>x.Target));Assert.AreEqual(1,Levels.SchemaVersion);}
 [Test,Category("T5S1")] public void UnlockUsesPredecessorCompletion(){Assert.IsTrue(Levels.IsUnlocked(1,new int[0]));Assert.IsFalse(Levels.IsUnlocked(2,new int[0]));Assert.IsTrue(Levels.IsUnlocked(2,new[]{1}));Assert.IsFalse(Levels.IsUnlocked(3,new[]{1}));Assert.IsTrue(Levels.IsUnlocked(3,new[]{2}));}
 [Test,Category("T5S1")] public void InvalidIdAndCopies(){Assert.IsFalse(Levels.IsUnlocked(0,new[]{1,2}));Assert.IsFalse(Levels.IsUnlocked(4,new[]{1,2,3}));var a=Levels.Catalog();a[0].Target=-1;Assert.AreEqual(100,Levels.Catalog()[0].Target);}
 [Test,Category("T5S2")] public void MenuUsesCatalogAndUnlockedState(){var go=new GameObject();try{var m=go.AddComponent<LevelMenu>();m.Render(new[]{1});var buttons=go.GetComponentsInChildren<Button>(true);Assert.AreEqual(3,buttons.Length);Assert.IsTrue(buttons[0].interactable);Assert.IsTrue(buttons[1].interactable);Assert.IsFalse(buttons[2].interactable);Assert.AreEqual(1,LevelMenu.ConsumedSchemaVersion);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test,Category("T5S2")] public void SelectionRespectsLockedLevel(){var go=new GameObject();try{var m=go.AddComponent<LevelMenu>();Assert.IsTrue(m.Select(1,new int[0]));Assert.AreEqual(1,m.SelectedId);Assert.IsFalse(m.Select(3,new int[0]));Assert.AreEqual(1,m.SelectedId);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test,Category("T5S2")] public void RenderIsIdempotentAndClickSelects(){var go=new GameObject();try{var m=go.AddComponent<LevelMenu>();m.Render(new[]{1,2});m.Render(new[]{1,2});var b=go.GetComponentsInChildren<Button>(true);Assert.AreEqual(3,b.Length);b[2].onClick.Invoke();Assert.AreEqual(3,m.SelectedId);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test,Category("T6S1")] public void CoreBoundsAndCollision(){var b=new bool[3,3];b[1,1]=true;var c=new BoardCore(b);Assert.IsFalse(c.CanPlace(1,1,new[]{new[]{0,0}}));Assert.IsFalse(c.CanPlace(2,2,new[]{new[]{0,0},new[]{1,0}}));Assert.IsTrue(c.CanPlace(0,0,new[]{new[]{0,0},new[]{1,0}}));}
 [Test,Category("T6S1")] public void PlacementAtomicAndDefensiveCopies(){var b=new bool[3,3];var c=new BoardCore(b);Assert.IsTrue(c.Place(0,0,new[]{new[]{0,0},new[]{1,0}}));Assert.IsFalse(b[0,0]);var snapshot=c.Snapshot();snapshot[0,0]=false;Assert.IsTrue(c.Snapshot()[0,0]);Assert.IsFalse(c.Place(1,0,new[]{new[]{0,0},new[]{0,1}}));Assert.IsFalse(c.Snapshot()[1,1]);}
 [Test,Category("T6S1")] public void InvalidOffsetsCannotMutate(){var c=new BoardCore(new bool[3,3]);Assert.IsFalse(c.Place(0,0,new[]{new[]{0,0},new[]{0,0}}));Assert.IsFalse(c.Snapshot()[0,0]);Assert.IsFalse(c.CanPlace(0,0,new int[0][]));Assert.AreEqual(1,BoardCore.ContractVersion);}
 [Test,Category("T6S1")] public void LegacyAdapterUsesExtractedCore(){var go=new GameObject();try{var legacy=go.AddComponent<LegacyBoard>();Assert.IsTrue(legacy.Put(1,1));Assert.IsNotNull(legacy.Core,"LegacyBoard must delegate to BoardCore");Assert.IsTrue(legacy.Core.Snapshot()[1,1]);Assert.IsFalse(legacy.Put(1,1));}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test,Category("T6S2")] public void CenterBombClearsNine(){var b=new bool[5,5];for(int x=0;x<5;x++)for(int y=0;y<5;y++)b[x,y]=true;var c=new BoardCore(b);Assert.AreEqual(9,c.Bomb(2,2));Assert.IsTrue(c.Snapshot()[0,0]);Assert.IsFalse(c.Snapshot()[2,2]);}
 [Test,Category("T6S2")] public void CornerBombClipsAndCountsOccupied(){var b=new bool[3,3];b[0,0]=b[1,0]=b[0,1]=true;var c=new BoardCore(b);Assert.AreEqual(3,c.Bomb(0,0));Assert.AreEqual(0,c.Bomb(0,0));}
 [Test,Category("T6S2")] public void InvalidBombNoOpAndVersionPreserved(){var b=new bool[2,2];b[0,0]=true;var c=new BoardCore(b);Assert.AreEqual(0,c.Bomb(-1,0));Assert.IsTrue(c.Snapshot()[0,0]);Assert.AreEqual(1,BoardCore.ContractVersion);}
}
